#!/usr/bin/env python3
import click
import requests
import os
import json
import time
import csv
from tabulate import tabulate
from typing import Optional

def validate_per_page(ctx, param, value):
    if value is None or not (1 <= value <= 100):
        raise click.BadParameter('per_page must be between 1 and 100')
    return value

@click.command()
@click.option('--person-locations', '-pl', multiple=True, help='Person locations (repeatable)')
@click.option('--organization-locations', '-ol', multiple=True, help='Organization locations (repeatable)')
@click.option('--person-titles', '-pt', multiple=True, help='Person titles (repeatable)')
@click.option('--person-seniorities', '-ps', multiple=True, help='Person seniorities (repeatable)')
@click.option('--per-page', '-pp', type=int, default=100, callback=validate_per_page, help='Per page (1-100)')
@click.option('--page', type=int, default=1, help='Page number')
@click.option('--preview', is_flag=True, help='Preview total and top 5 table')
@click.option('--full', is_flag=True, help='Full enrich and output to file')
@click.option('--output-file', '-o', type=str, help='Output file (.csv or .json) for --full')
@click.option('--enrich-count', type=int, default=25, help='Number of top people to enrich')
@click.option('--reveal-personal-emails', is_flag=True, default=False, help='Reveal personal emails in bulk_match')
def apollo_search(
    person_locations,
    organization_locations,
    person_titles,
    person_seniorities,
    per_page,
    page,
    preview,
    full,
    output_file,
    enrich_count,
    reveal_personal_emails,
):
    if not preview and not full:
        click.echo(click.style('Specify --preview or --full', fg='red'))
        return

    api_key = os.environ.get('APOLLO_API_KEY')
    dry_run = not api_key
    headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
    }
    if api_key:
        headers['Authorization'] = f'Bearer {api_key}'

    base_url = 'https://api.apollo.io/v1'
    session = requests.Session()
    session.headers.update(headers)

    # Build search body
    body = {
        'per_page': per_page,
        'page': page,
    }
    if person_locations:
        body['person_locations'] = list(person_locations)
    if organization_locations:
        body['organization_locations'] = list(organization_locations)
    if person_titles:
        body['person_titles'] = list(person_titles)
    if person_seniorities:
        body['person_seniorities'] = list(person_seniorities)
    if full:
        body['has_email'] = True

    search_url = f'{base_url}/mixed_people/api_search'

    if dry_run:
        print('DRY RUN (no APOLLO_API_KEY set)')
        print('Search Headers:')
        print(json.dumps(headers, indent=2))
        print('Search Body:')
        print(json.dumps(body, indent=2))
        if full:
            print(f'Would filter people with has_email, take top {enrich_count} ids, batch enrich (batches <=10, size~10)')
            print('Example bulk_match params: reveal_personal_emails=False')
            print('Example bulk body: {"ids": ["person_id1", "person_id2"]}')
        return

    def request_with_retry(session, method, url, json=None, params=None):
        for attempt in range(3):
            try:
                resp = session.request(method, url, json=json, params=params)
                if resp.status_code == 429:
                    wait = (2 ** attempt) + (attempt * 0.1)  # exp backoff
                    click.echo(f'Rate limit hit, waiting {wait:.1f}s (attempt {attempt+1}/3)')
                    time.sleep(wait)
                    continue
                if resp.ok:
                    return resp.json()
                else:
                    click.echo(f'API error {resp.status_code}: {resp.text[:200]}...')
                    return None
            except Exception as e:
                click.echo(f'Request exception: {str(e)}')
                if attempt == 2:
                    raise
                time.sleep(2 ** attempt)
        return None

    # Perform search
    search_data = request_with_retry(session, 'POST', search_url, json=body)
    if not search_data or 'people' not in search_data:
        click.echo('Search failed or no people found')
        return

    people = search_data['people']
    pagination = search_data.get('pagination', {})
    total_entries = pagination.get('total_entries', len(people))
    click.echo(f'Total entries found: {total_entries}')

    if preview:
        def obfuscate_last_name(name):
            if not name or len(name) < 2:
                return name or ''
            return name[0] + '*' * (len(name) - 2) + name[-1]

        table_data = []
        for p in people[:5]:
            first_name = p.get('first_name', '')
            last_name = obfuscate_last_name(p.get('last_name', ''))
            title = p.get('title', {}).get('name', p.get('title', '')) if p.get('title') else ''
            org_name = p.get('organization', {}).get('name', '') if p.get('organization') else ''
            table_data.append([first_name, last_name, title, org_name])

        click.echo(tabulate(table_data, headers=['First Name', 'Last Name', 'Title', 'Organization'], tablefmt='grid'))
        return

    if full:
        # Filter already done via has_email in search
        if len(people) < enrich_count:
            enrich_count = len(people)
        ids = [p['id'] for p in people[:enrich_count]]

        if not ids:
            click.echo('No people to enrich')
            return

        if not output_file:
            click.echo(click.style('--output-file required for --full', fg='red'))
            return

        batch_size = 10
        enriched_people = []
        bulk_url = f'{base_url}/people/bulk_match'
        params = {'reveal_personal_emails': reveal_personal_emails}

        for i in range(0, len(ids), batch_size):
            batch_ids = ids[i:i + batch_size]
            bulk_body = {'ids': batch_ids}
            batch_data = request_with_retry(session, 'POST', bulk_url, json=bulk_body, params=params)
            if batch_data and 'people' in batch_data:
                enriched_people.extend(batch_data['people'])
            else:
                click.echo(f'Batch {i//batch_size +1} enrich failed')

        # Prepare data
        fields = ['first_name', 'last_name', 'title', 'email', 'organization_name', 'city', 'state', 'email_status']
        output_data = []
        for p in enriched_people:
            row = {}
            row['first_name'] = p.get('first_name', '')
            row['last_name'] = p.get('last_name', '')
            title = p.get('title', {})
            row['title'] = title.get('name', '') if isinstance(title, dict) else title
            row['email'] = p.get('email', '')
            org = p.get('organization', {}) or p.get('current_company', {})
            row['organization_name'] = org.get('name', '')
            row['city'] = p.get('city', '')
            row['state'] = p.get('state', '')  # or region
            row['email_status'] = p.get('email_status', 'unknown')
            output_data.append(row)

        # Write file
        _, ext = os.path.splitext(output_file)
        try:
            if ext.lower() == '.csv':
                with open(output_file, 'w', newline='', encoding='utf-8') as f:
                    writer = csv.DictWriter(f, fieldnames=fields)
                    writer.writeheader()
                    writer.writerows(output_data)
            elif ext.lower() == '.json':
                with open(output_file, 'w', encoding='utf-8') as f:
                    json.dump(output_data, f, indent=2)
            else:
                click.echo('Unsupported extension. Use .csv or .json')
                return
            click.echo(f'Successfully wrote {len(output_data)} records to {output_file}')
        except Exception as e:
            click.echo(f'Error writing file: {e}')

if __name__ == '__main__':
    apollo_search()
EOF

